#!/bin/sh
# Builds JRAI.EXE (Open Watcom, 8088, large model, warnings are errors).
# speech.c is generated by genspeech.py (needs node and sam-js); it is
# kept in the repo so a normal build doesn't need either.
set -e
cd "$(dirname "$0")"
. ../../client/owenv.sh
LIB=../../lib
SRC="main.c music.c draw.c boot.c plasma.c fire.c tunnel.c meet.c scroll.c speech.c"
wcl -q -bt=dos -ml -0 -ox -wx -we -i=$LIB -fe=JRAI.EXE $SRC $LIB/jrgfx.lib
rm -f *.o *.err
ls -l JRAI.EXE
